mapper.select:
SELECT id, order_date, (SELECT cln.name FROM clients cln WHERE cln.client_code = sales_order.client_code LIMIT 1) AS client_name, client_code, (SELECT CASE WHEN pdn.spec IS NOT NULL AND pdn.spec != '' THEN pdn.name || '(' || pdn.spec || ')' ELSE pdn.name END FROM products pdn WHERE pdn.code = sales_order.product_code) AS product_name, product_code, order_qty, note, production_date, logistics_date, is_stock_production, imported, imported_production, imported_shipment, sort_order, created_at FROM sales_order
order_date = #{_parameter}
ORDER BY production_date, sort_order, id

SELECT MAX(sort_order)
FROM sales_order
WHERE order_date = #{orderDate}

SELECT CASE WHEN COALESCE(imported_production, 0) = 1 OR COALESCE(imported_shipment, 0) = 1 THEN 1 ELSE 0 END
FROM sales_order
WHERE id = #{id}

SELECT code
FROM products
WHERE code = #{code}

SELECT code
FROM products
WHERE name = #{name}
  AND spec = #{spec}

SELECT code
FROM products
WHERE name = #{name}
